21	@Slf4j
22	@Service
23	public class BpmEventListener {
24	
25	    @Autowired
26	    private EventDrivenSubscriber eventDrivenSubscriber;
27	
28	    @Autowired
29	    private EventDrivenProperties eventDrivenProperties;
30	
31	    @EntryTrace
32	    @KafkaListener(id = "bpm-home-starlord",idIsGroup = false,topics = {"${bpm-home-starlord.kafka.topic}"}, containerFactory = "${kafka.config.cluster23.consumer.properties.listener-names}")
33	    public void bpmEventListen(ConsumerRecord<String, String> cr){
34	
35	        try {
36	            BpmMsgBO bpmMsg = JsonUtils.jsonStr2Obj(cr.value(), BpmMsgBO.class);
37	            EventSub eventSub = convertEventSub(bpmMsg);
38	            eventDrivenSubscriber.persistAndHandleMessage(eventSub);
39	
40	        }catch (Exception e){
41	            log.error("bpm listen error . msg:{} . ",cr.value(),e);
42	        }
43	    }
44	
45	
46	    private EventSub convertEventSub(BpmMsgBO bpmMsg) {
47	        String eventType = EventTypeUtils.generateEventType("utopia", "bpm",bpmMsg.getProcessDefId() );
48	        final EventSub eventSub = new EventSub();
49	        eventSub.setEventId(bpmMsg.getKeMsgId());
50	        eventSub.setEventType(eventType);
51	        eventSub.setEventContextKey(bpmMsg.getProcessInstId());
52	        eventSub.setEventOccurTime(new Date());
53	        eventSub.setEventGroup(eventDrivenProperties.getServerGroup());
54	        String serverName = eventDrivenProperties.getServerName();
55	        eventSub.setEventService(serverName);
56	        eventSub.setPayloadData(Jacksons.parse(bpmMsg));
57	        eventSub.setLockVersion(EventDrivenContent.EVENT_LOCK_VERSION);
58	        eventSub.setEventStatus(EventStatus.NEW.getType());
59	        return eventSub;
60	    }
